        "reason": "1. 消费电子业务增长稳健，端侧AI空间广阔\n25年公司消费电子业务实现营收2642.66亿元，同比增加13.37%；毛利率为10.64%，同比增加1.16pcts。借由对ODM业务及研发团队的整合，推动海量精密零组件与模组产品加速向新老客户导入，有望持续拓宽消费电子业务的边界与护城河。\n2. 汽车电子业务业绩高增，完成对莱尼集团的交割与全面整合\n25年公司汽车电子业务实现营收392.55亿元，同比增加185.34%；毛利率为15.75%，同比减少0.35pcts。25年公司正式完成对德国百年汽车零部件巨头莱尼集团的交割与全面整合，打通公司直通欧洲、美洲及日韩等海外主流车企核心供应链的通道，拉动既有产品份额攀升，加速智高附加值产品导入。\n3. 通信及数据中心业务受益AI浪潮，光互连/散热等多领域布局\n25年公司通讯及数据中心业务实现营收245.68亿元，同比增加33.81%；毛利率为18.40%，同比增加2.00pcts。光互连领域，800G/1.6T光模块已进行小批量供货；电源领域，推出Busbar、Powershelf等智能电源系统以及高功率模块电源；热管理领域，提供包括120kW液液交换CDU等多元化液冷方案。AIDC多领域布局有望充分受益AI浪潮，持续驱动业绩增长。 | 1、消费电子方面，立讯仍是苹果产业链中具备全球产能布局能力和优秀成本效率的优秀代表，苹果Apple Intelligence升级仍值得期待，折叠机、AI耳机、XR等新终端和光学、结构件等多方面的零部件创新公司仍在全面参与，公司对和硕手机、闻泰Mac和Qorvo射频模组等资产的整合和效率提升仍有空间，公司维持中长线苹果业务稳健增长仍无虑；非A消费电子部分，公司以“场景生态、AI赋能、全球协同”三位一体战略和以“垂直整合+场景创新”双轮驱动，在OEM和ODM领域完成从零部件到系统方案的全链条突破。\n2、通信业务方面，公司持续深耕电连接、光连接、风冷/液冷散热、电源管理、射频等产品，以“应用一代，开发一代，预研一代”为产品核心战略，构建起强大的技术壁垒和市场竞争力。尤其在数据中心高速互联领域，公司协同头部芯片厂商前瞻性为全球主流数据中心及云服务厂商共同制定 800G、1.6T 等下一代高速连接标准，部分细分领域产品如外部高速铜缆、线缆及连接器组件、背板连接器及背板线缆、HSIO、SSIO 等更是以领先的技术、成本优势和优异的产品表现赢得了客户的认可。在此基础上，公司以此为切入口，全面拉动光连接、散热、电源模块等产品与头部客户展开进一步深度合作，打开长线业务空间；\n3、汽车业务方面，公司依托强大的智能制造平台，快速实现向汽车产业相关产品的跨界赋能，并基于与海内外头部主机厂和汽车品牌客户的深度战略合作伙伴关系，为汽车业务相关产品打开了广阔的市场空间，近期收购莱尼线束业务叠加后续布局，为在未来三个五年实现成为全球汽车零部件 Tier1 领导厂商的中长期目标奠定坚实的基础。\n4、公司业绩基本面兑现能力强，未来数年业绩快速复合增长确定，当前低估价值凸显，长线空间可观。",
