        "reason": "光通布局逐渐深化，开启进阶新征程。\n一、推荐逻辑\n公司于2023年果决依托LED在第三代半导体的积累，以及自身终端制造能力优势，切入光通领域，并快速从行业入门做到行业领先，当下兆驰光芯片、光器件、光模块的全产业链布局已经完备，羽翼渐丰，未来如果关键客户ODM产品导入顺利的话，兆驰完全有可能成为行业头部光模块制程全产业链一体化的头部玩家。\n从今年来看，下半年是兆驰格局跃迁的关键时点：1）过往两年贸易战与面板成本上行带来的电视ODM业务负面影响已经边际递减。2）LED芯片、封装，尤其是低端照明领域缺货，产品价格持续上行，LED全产业链的盈利弹性将快速显现。3）光通关键客户导入，产品进阶，芯片逐渐自制全产业链拉通，未来盈利提升可期。4）Micro led光通是服务器互连的重要瓶颈项，在这一领域，兆驰始终是占据最多产业链关键点的头部玩家。",
