        "change": "新增",
        "reason": "对中式零食成长空间保有信心，聚焦三大品类打造丰富产品矩阵，目标世界级品牌。会上董事长张学武作分享，公司将持续聚焦“中国风味零食”、“健康高蛋白零食”与“健康甜味零食”三大黄金赛道，矢志为中国贡献一个世界级的休闲零食品牌。具体来看，魔芋、豆制品是中国风味的最佳载体；健康蛋白零食方向，公司孵化的“蛋皇”鹌鹑蛋等产品已凭借极致创新获得市场认可，公司还会持续整合全球鳕鱼等优质资源拓展健康蛋白零食；在健康甜味零食品类，公司已建立起包括全球领先大片芒果干在内的产品矩阵，并持续推动健康化升级。\n公司逐步从渠道型公司转型为产品型公司，继续朝品牌型公司前进。围绕“做好产品”这一使命，公司在商业模式层面持续进化，已经在“深耕源头供应链、打造智能制造标杆、坚持创新驱动、成功打造品牌”四个维度构建强劲综合竞争力。过去公司的成长动力主要源自渠道红利的把握，而绑定新兴强势的量贩渠道后对大单品的反哺能力大幅提升，2023年10月“大魔王”魔芋大单品面市，2025年3月单口味单月销售额突破亿元，8月月销破2亿，魔芋已成为公司最重要的现象级大单品。在成功打造鹌鹑蛋和魔芋大单品的基础上，公司品牌营销再上台阶，进入用品牌去放大品类势能的新阶段，公司在本次发布会前夕官宣青年演员、歌手王一博为“大魔王”品牌全球代言人。魔芋品类还将助力公司全球化，“大魔王”品牌自诞生即定位全球化，产品已销往25个国家和地区，与泰国7-11、新加坡思家客、美国99大华超市等主流渠道合作。\n2025年借大单品之势优化渠道，增长质量更高，长生命周期成长正启航。2025年公司渠道端全面出击，依托魔芋爆品加速终端拓展和覆盖，定量流通渠道高速成长；会员制商超合作良性， 11月上市“蛋皇”溏心鹌鹑蛋快速进入新品热卖榜；量贩以及众多省钱超市等新业态仍有较大空间。线下渠道形势好，公司主动收缩电商销售，重点清理贴牌和高费用低盈利产品，带来利润率上升。在大单品成长不断验证趋势下，公司全面而均衡化发展渠道，渠道端基本盘优势预计会愈发明显，“产品力，渠道力，品牌力”相互促进，更加稳固，由此我们看到公司在快速发展中保持战略清醒，未来成长动能不断增强。市场短期容易低估公司综合竞争力跃升后的成长空间，对头部零食的长期成长保有信心。",
