        "reason": "“确定性底盘 + 高弹性期权”。2026年看进口片修复带动发行板块回暖，2027-2028年看《流浪地球3》上下部接力释放，中国电影将从“平台稳态估值”切换到“内容大年弹性估值”。\n\n一、超预期逻辑\n1、2026年并非纯粹“过渡年”，进口片可能先抬升盈利中枢。2026年，北美定档的头部IP续作明显丰富，包括《玩具总动员5》、《蜘蛛侠：崭新之日》、《复仇者联盟5：毁灭之日》、《小黄人大眼萌3》、《饥饿游戏：收获日出》、《沙丘3》等，尤具票房潜力。中国电影作为进口片发行核心平台，2025年已实现进口片发行票房份额64.8%，因此2026年进口片若维持高供给，公司发行板块收入与利润有望先于创作板块修复。\n2、《流浪地球3》不是单片弹性，而是两年维度的连续弹性。《流浪地球3》上部已经定档2027年2月6日（春节档），而下部有望在2028年上映。这一定档结构的关键意义在于，市场通常只把它当作2027年的一次性事件，但实际上它更可能形成2027-2028两年连续释放。前两部作品已经验证该IP的票房天花板：《流浪地球》2019年票房46.87亿元，《流浪地球2》2023年票房40.43亿元，累计超过87亿元。作为《流浪地球3》上下部的主出品方，中国电影有望跨两个会计年度实现创作、发行、放映多环节超预期收益。这也是本文最大的核心判断之一。",
